import {mainQuery} from '@github-ui/react-core/future/main-query'
import {copilotAgentPlaneAppBuilder} from '../config/app-builder'

export type AgentCategory = 'coding_session' | 'code_review' | 'other'

export type SessionData = {
  id: string
  status: string
  status_display: string
  status_icon: string
  title: string
  url?: string
  agent?: {
    name: string
    category?: AgentCategory
  }
  repository: {
    owner: string
    name: string
    full_name: string
  }
  started_at: string
  time_since_start: string
  event_type?: string
  accessible?: boolean
}

export type PaginationData = {
  current_page: number
  total_pages: number
  total_count: number
  per_page: number
  has_previous: boolean
  has_next: boolean
}

export type OrganizationData = {
  id: number
  name: string
}

export type AgentFilterData = {
  value: string
  display_name: string
  avatar_url: string
}

export type StatusFilterData = {
  name: string
  display_name: string
}

export type TimeframeFilterData = {
  value: string
  display_name: string
  number: number
}

export type SessionsResponse = {
  sessions: SessionData[]
  pagination: PaginationData
  heading: string
  organizations?: OrganizationData[]
  agent_filters?: AgentFilterData[]
  timeframe_filters?: TimeframeFilterData[]
  status_display_names?: StatusFilterData[]
}

export const sessionsRoute = copilotAgentPlaneAppBuilder.createQueryRouteConfig('sessionsRoute', {
  path: '/enterprises/:slug/ai-controls/agents/sessions',
  queries: [
    mainQuery<SessionsResponse>({
      queryDeps: ({pathname, searchParams}) => ({
        pathname,
        searchParams: {
          query: searchParams.get('query'),
          agent_type: searchParams.get('agent_type'),
          page: searchParams.get('page'),
          organization_id: searchParams.get('organization_id'),
        },
      }),
    }),
  ],
})
