import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRuntimeEnvironment} from '@github-ui/ssr-utils/use-runtime-environment'
import {useLocalStorage} from '@github-ui/use-safe-storage/local-storage'
import {agentsRoute, type CustomAgent} from './agents-route'
import {useParams} from '@github-ui/react-router'
import {LogIcon, BlockedIcon, CheckCircleIcon, CopilotIcon, AgentIcon, XIcon} from '@primer/octicons-react'
import {Banner, Button, IconButton, Link, PageHeader, Stack, Text, Spinner, Label} from '@primer/react'
import {Blankslate, SkeletonText} from '@primer/react/experimental'
import {ControlGroup as ControlGroupNew} from '@github-ui/control-group'
import {EnterpriseControlGroup} from '@github-ui/enterprise-control-group'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {AppProviders} from '../components/AppProviders'
import {PageBanner} from '../components/PageBanner'
import {useState, useEffect} from 'react'
import {SelectOrgPicker} from '../components/SelectOrgPicker'
import type {SuggestedOrg} from '../types'
import {ProtectAgents} from '../components/ProtectAgents'
import {EnterpriseManagedSettings} from '../components/EnterpriseManagedSettings'
import {ConfigurationSummary} from '../components/ConfigurationSummary'
import {useRecentSessions} from '../hooks/use-recent-sessions'
import {getStatusIcon, getStatusProgress} from '../components/IconStatus'
import {Constants} from '../constants'
import styles from './Agents.module.css'
import {fetchCustomAgents, toggleThirdPartyAgent} from '../hooks/use-custom-agents'
import {ThirdPartyAgentMode, ThirdPartyAgentSelector, type ThirdPartyAgent} from '../components/ThirdPartyAgentSelector'

const Status = {
  enabled: 'Enabled',
  disabled: 'Disabled',
} as const
type Status = (typeof Status)[keyof typeof Status]

type Agent = {
  name: string
  status: Status
  policy?: string
  policyDisplayText?: string
}

export function Agents() {
  return (
    <AppProviders>
      <InnerAgents />
    </AppProviders>
  )
}
export function InnerAgents() {
  const controlGroupUnificationEnabled = isFeatureEnabled('control-group-unification')
  const ControlGroup = controlGroupUnificationEnabled ? ControlGroupNew : EnterpriseControlGroup

  const payload = useRouteQuery(agentsRoute, 'mainQuery')
  const {slug} = useParams<{slug: string}>()
  const {isBrowser} = useRuntimeEnvironment()

  const canWrite = payload.data?.can_write ?? false
  const canAdmin = payload.data?.can_admin ?? false
  const canViewAuditLogs = payload.data?.can_view_audit_logs ?? false
  const canViewThirdPartyAgents = payload.data?.can_view_third_party_agents ?? false
  const thirdPartyAgentsEnabled = payload.data?.third_party_agents_enabled ?? false

  const enterpriseManagedClientSettings = payload.data?.enterprise_managed_client_settings
  // Wrapper present means the server returned a source repo (with or without a parsed settings.json)
  const hasSourceRepo = !!enterpriseManagedClientSettings
  // Inner settings present means the source repo has a parsed settings.json
  const hasEnterpriseManagedClientSettings = !!enterpriseManagedClientSettings?.settings

  // Compute selection from payload source_org
  const payloadSelection = payload.data?.source_org?.id
    ? {
        id: payload.data.source_org.id,
        name: payload.data.source_org.name || '',
        primaryAvatarUrl: payload.data.source_org.avatar_url || '',
      }
    : null

  const [selection, setSelection] = useState<SuggestedOrg | null>(payloadSelection)
  const [validationWarning, setValidationWarning] = useState(false)
  const [validationLoading, setValidationLoading] = useState(false)
  const [customAgents, setCustomAgents] = useState<CustomAgent[]>([])
  const [isLoadingCustomAgents, setIsLoadingCustomAgents] = useState(false)
  const [hasLoadedInitialPayload, setHasLoadedInitialPayload] = useState(false)
  const [thirdPartyAgentModes, setThirdPartyAgentModes] = useState<Record<string, ThirdPartyAgentMode>>({})
  const [toggleNotification, setToggleNotification] = useState<{
    type: 'error' | 'success'
    message: string
  } | null>(null)

  // Use payload selection if no user selection has been made
  const currentSelection = selection || payloadSelection

  const agents: Agent[] =
    payload.data?.agents?.map(agent => {
      let status: Status
      let policyDisplayText: string

      switch (agent.policy) {
        case 'no_policy':
          status = Status.enabled
          policyDisplayText = 'Defined by organization'
          break
        case 'enabled':
          status = Status.enabled
          policyDisplayText = 'Enabled'
          break
        case 'unconfigured':
          status = Status.disabled
          policyDisplayText = 'Unconfigured'
          break
        case 'coding_agent_enterprise_management':
          status = Status.enabled
          policyDisplayText = 'Enabled for selected organizations'
          break
        default:
          status = Status.disabled
          policyDisplayText = 'Disabled'
      }

      return {
        name: agent.name,
        status,
        policyDisplayText,
        policy: agent.policy,
      }
    }) || []

  const [hideAgentsUpsellBanner, setHideAgentsUpsellBanner] = useLocalStorage(
    Constants.AGENTS_UPSELL_BANNER_HIDDEN_STORAGE_KEY,
    false,
  )
  const isCCAEnabled = agents.some(
    agent => agent.name.toLowerCase() === 'copilot cloud agent' && agent.status === Status.enabled,
  )

  const isAgentsPromoVisible = isBrowser && !hideAgentsUpsellBanner && !isCCAEnabled

  const thirdPartyAgents: ThirdPartyAgent[] =
    payload.data?.third_party_agents?.map(agent => {
      return {
        name: agent.name,
        mode: agent.enabled ? ThirdPartyAgentMode.allowed : ThirdPartyAgentMode.disabled,
        docUrl: agent.doc_url,
        toggleUrl: agent.toggle_url,
        integration: {
          avatarUrl: agent.integration.avatar_url,
        },
      }
    }) || []

  // Initialize third-party agent modes from payload
  useEffect(() => {
    if (payload.data?.third_party_agents) {
      const initialModes: Record<string, ThirdPartyAgentMode> = {}
      for (const agent of payload.data.third_party_agents) {
        initialModes[agent.name] = agent.enabled ? ThirdPartyAgentMode.allowed : ThirdPartyAgentMode.disabled
      }
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setThirdPartyAgentModes(initialModes)
    }
  }, [payload.data?.third_party_agents])

  // Consume initial payload on page load
  useEffect(() => {
    async function loadInitialData() {
      if (payload.data && !hasLoadedInitialPayload) {
        if (payload.data.source_org?.id) {
          setSelection({
            id: payload.data.source_org.id,
            name: payload.data.source_org.name || '',
            primaryAvatarUrl: payload.data.source_org.avatar_url || '',
          })
          // If there's a source org in the payload, it's already validated
          setValidationWarning(false)
          // Load custom agents for the source org
          if (slug) {
            setIsLoadingCustomAgents(true)
            try {
              const data = await fetchCustomAgents({slug})
              setCustomAgents(data.custom_agents)
            } catch {
              setCustomAgents([])
            } finally {
              setIsLoadingCustomAgents(false)
            }
          }
        }
        setHasLoadedInitialPayload(true)
      }
    }
    void loadInitialData()
  }, [payload.data, hasLoadedInitialPayload, slug])

  // Handle third-party agent mode changes
  const handleThirdPartyAgentModeChange = async (agentName: string, toggleUrl: string, newMode: string) => {
    setToggleNotification(null)
    const currentMode = thirdPartyAgentModes[agentName]

    // Optimistically update UI
    setThirdPartyAgentModes(prev => ({
      ...prev,
      [agentName]: newMode as ThirdPartyAgentMode,
    }))

    try {
      await toggleThirdPartyAgent({
        toggleUrl,
        enable: newMode === ThirdPartyAgentMode.allowed,
      })

      setToggleNotification({
        type: 'success',
        message: `Successfully updated ${agentName} settings.`,
      })
    } catch {
      // Revert on error
      if (currentMode !== undefined) {
        setThirdPartyAgentModes(prev => ({
          ...prev,
          [agentName]: currentMode,
        }))
      }
      setToggleNotification({
        type: 'error',
        message: `Failed to update ${agentName}. Please try again.`,
      })
    }
  }

  // Fetch custom agents after successful org validation
  const handleValidationSuccess = async (hasMarker: boolean) => {
    setValidationWarning(!hasMarker)
    if (hasMarker && slug) {
      setIsLoadingCustomAgents(true)
      try {
        const data = await fetchCustomAgents({slug})
        setCustomAgents(data.custom_agents)
      } catch {
        setCustomAgents([])
      } finally {
        setIsLoadingCustomAgents(false)
      }
    }
  }

  const handleHideUpsellBanner = () => {
    setHideAgentsUpsellBanner(true)
  }

  const {data: recentSessionsData, isLoading: sessionsLoading} = useRecentSessions({slug: slug || '', limit: 3})

  return (
    <Stack gap="spacious" padding="none">
      {!canAdmin && (
        <Banner
          variant="info"
          title="Read-only access"
          hideTitle
          description="Some settings may be restricted depending on your access level. Contact an enterprise owner to make changes."
          className="tmp-mb-3"
        />
      )}
      {toggleNotification && (
        <Banner
          variant={toggleNotification.type === 'error' ? 'critical' : 'success'}
          title={toggleNotification.type === 'error' ? 'Error' : 'Success'}
          hideTitle
          description={toggleNotification.message}
          onDismiss={() => setToggleNotification(null)}
        />
      )}
      <PageHeader className="pb-2" aria-label="Title">
        <PageHeader.TitleArea>
          <PageHeader.Title className="pb-2 h3" as="h1">
            Agents
          </PageHeader.Title>
        </PageHeader.TitleArea>
        <PageHeader.Description className="border-top border-color-border-default flex flex-column flex-items-start">
          {isAgentsPromoVisible && (
            <Stack
              direction="horizontal"
              role="region"
              /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
              aria-label="Enable GitHub Copilot Agents"
              className={styles.AgentsUpsellBanner}
            >
              <Stack gap="normal" className={styles.AgentsUpsellContent}>
                {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
                <h2 className="h3 m-0">Enable GitHub Copilot Agents</h2>
                <p className="fgColor-muted text-large f4 m-0">
                  Copilot cloud agent resolves issues autonomously. Code Review catches bugs on every pull request.
                  Enable both to get the most out of Copilot.
                </p>
                <Stack direction="horizontal" gap="condensed" wrap="wrap">
                  {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
                  <Button as="a" href="agents/policies" variant="primary">
                    Enable in Agent Policies
                  </Button>
                </Stack>
              </Stack>
              <Stack align="center" justify="center" aria-hidden="true" className={styles.AgentsUpsellIllustration}>
                <CopilotIcon size={64} />
              </Stack>
              <IconButton
                aria-label="Dismiss GitHub Copilot Agents banner"
                icon={XIcon}
                onClick={handleHideUpsellBanner}
                size="small"
                variant="invisible"
                className={styles.AgentsUpsellDismissButton}
              />
            </Stack>
          )}
          <span className="fgColor-muted d-block width-full text-left">
            Manage agent configuration and enable new custom agents for your enterprise users by selecting existing
            configuration files.{' '}
            <Link inline href="https://docs.github.com/copilot/concepts/agents/coding-agent/about-custom-agents">
              Learn more about custom agents.
            </Link>
          </span>
        </PageHeader.Description>
      </PageHeader>
      <PageBanner />

      <Stack gap="condensed">
        <h2>Enterprise-provided configuration</h2>
        <p className="fgColor-muted text-small m-0">
          Applies to Copilot CLI and Copilot Cloud Agent.{' '}
          <Link
            inline
            href="https://docs.github.com/copilot/how-tos/administer-copilot/manage-for-enterprise/manage-agents/configure-enterprise-plugin-standards"
          >
            Learn more about configuring enterprise-managed AI standards for Copilot clients.
          </Link>
        </p>
      </Stack>

      <Stack gap="normal">
        <div className={styles.CustomAgentsHeader}>
          <div>
            <h3 className="h4">Configuration source</h3>
            <p className="fgColor-muted text-small m-0">
              Select the organization that provides enterprise-managed settings, plugins, and custom agents.
            </p>
          </div>
          {slug && (
            <SelectOrgPicker
              selection={currentSelection}
              onChange={setSelection}
              onValidation={handleValidationSuccess}
              onValidationLoading={loading => setValidationLoading(loading)}
              slug={slug}
              disabled={!canWrite}
            />
          )}
        </div>

        {hasSourceRepo &&
          (validationLoading ? (
            <div className="d-flex flex-items-center flex-justify-center height-full tmp-py-3 tmp-mb-3">
              <div className="mr-2">
                <Spinner size="small" />
              </div>
              <div className="small-text color-fg-muted">Validating selected organization…</div>
            </div>
          ) : (
            <ControlGroup>
              <ControlGroup.Item
                leadingIcon={currentSelection?.primaryAvatarUrl ? undefined : <AgentIcon />}
                leadingVisual={
                  currentSelection?.primaryAvatarUrl ? (
                    <img
                      src={currentSelection.primaryAvatarUrl}
                      alt=""
                      className={styles.SourceOrganizationAvatar}
                      data-testid="source-organization-avatar"
                      aria-hidden="true"
                    />
                  ) : undefined
                }
              >
                <ControlGroup.Title>{currentSelection?.name}</ControlGroup.Title>
                <ControlGroup.Description>
                  <span>
                    {enterpriseManagedClientSettings?.display_name_with_owner ? (
                      <>
                        Configuration is sourced from{' '}
                        <strong>{enterpriseManagedClientSettings.display_name_with_owner}</strong>.
                      </>
                    ) : (
                      <>Configuration is sourced from the selected organization&apos;s .github-private repository.</>
                    )}
                  </span>
                </ControlGroup.Description>
                {enterpriseManagedClientSettings?.source_repo_url && (
                  <ControlGroup.Custom>
                    <Link
                      href={enterpriseManagedClientSettings.source_repo_url}
                      target="_blank"
                      rel="noopener noreferrer"
                      aria-label="View source repository (opens in a new window)"
                    >
                      View repository
                    </Link>
                  </ControlGroup.Custom>
                )}
              </ControlGroup.Item>
            </ControlGroup>
          ))}
        {validationWarning && !validationLoading && (
          <Banner
            aria-label="Info with actions"
            title="Info"
            hideTitle
            variant="warning"
            description={
              <span>
                Selected organization does not include a <b>.github-private</b> repository, please select another.
                <Link
                  href="https://docs.github.com/en/enterprise-cloud@latest/copilot/concepts/agents/coding-agent/about-custom-agents#where-you-can-configure-custom-agents"
                  className="ml-1"
                  target="_blank"
                  rel="noopener noreferrer"
                  aria-label="Learn more about configuring custom agents (opens in a new window)"
                >
                  Learn more about configuring custom agents.
                </Link>
              </span>
            }
          />
        )}
      </Stack>

      {hasSourceRepo && enterpriseManagedClientSettings && (
        <ConfigurationSummary settings={enterpriseManagedClientSettings} customAgentsCount={customAgents.length} />
      )}

      {hasEnterpriseManagedClientSettings && enterpriseManagedClientSettings?.settings && (
        <EnterpriseManagedSettings settings={enterpriseManagedClientSettings.settings} />
      )}

      <Stack gap="normal">
        <div className="d-flex flex-row flex-items-center flex-justify-between">
          <h2>Agent sessions</h2>
          <span className="ml-2 text-small fgColor-muted">Last 24 hours</span>
        </div>
        {sessionsLoading ? (
          <div className="border rounded-2" role="status" aria-label="Loading recent sessions">
            {[1, 2, 3].map(i => (
              <div
                key={i}
                className="Box-row d-flex flex-row flex-items-start gap-3 tmp-py-3"
                style={{borderTop: i > 1 ? '1px solid var(--borderColor-default)' : 'none'}}
              >
                <div className="flex-1">
                  <div className="mb-2">
                    <SkeletonText size="bodyMedium" />
                  </div>
                  <div style={{width: '70%'}}>
                    <SkeletonText size="bodySmall" />
                  </div>
                </div>
                <div style={{width: '120px'}}>
                  <SkeletonText size="bodySmall" />
                </div>
              </div>
            ))}
          </div>
        ) : recentSessionsData?.sessions && recentSessionsData.sessions.length > 0 ? (
          <ControlGroup>
            {recentSessionsData.sessions.slice(0, 3).map(session => (
              <ControlGroup.Item
                key={session.id}
                leadingVisual={
                  <div style={{paddingLeft: '2px', paddingTop: '1px'}}>{getStatusIcon(session.status)}</div>
                }
              >
                <ControlGroup.Title>
                  {session.url ? (
                    <Link href={session.url} className="Link--primary no-underline">
                      {session.title}
                    </Link>
                  ) : (
                    <span>{session.title}</span>
                  )}
                </ControlGroup.Title>
                <ControlGroup.Description>
                  <div className="text-small fgColor-muted">
                    <Link href={`/${session.repository.full_name}`} className="Link--muted">
                      {session.repository.full_name}
                    </Link>
                    <span className="mx-1">·</span>
                    <span>Started {session.time_since_start}</span>
                  </div>
                </ControlGroup.Description>
                <ControlGroup.Custom>
                  <div className="d-flex flex-row flex-items-center gap-2">
                    <span className="text-small">{session.status_display}</span>
                    <div className="Progress" style={{width: '105px', height: '3px', marginTop: '2px'}}>
                      <div
                        className="Progress-item"
                        style={{
                          width: `${getStatusProgress(session.status)}%`,
                          backgroundColor: '#0969da',
                        }}
                      />
                    </div>
                  </div>
                </ControlGroup.Custom>
              </ControlGroup.Item>
            ))}
            <ControlGroup.Item href="agents/sessions">
              <ControlGroup.Title>
                <Text size="small">View all</Text>
              </ControlGroup.Title>
            </ControlGroup.Item>
          </ControlGroup>
        ) : (
          <div className="Box-row tmp-py-6 text-center fgColor-muted">No recent sessions found.</div>
        )}
      </Stack>

      <Stack gap="normal">
        {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
        <h2>Available Agents</h2>

        <Stack gap="normal">
          <div className="fgColor-muted">
            <Text weight="semibold">GitHub</Text>
          </div>
          <ControlGroup>
            {agents.map(agent => (
              <ControlGroup.Item href="agents/policies" leadingIcon={<CopilotIcon />} key={agent.name}>
                <ControlGroup.Title>{agent.name}</ControlGroup.Title>
                <ControlGroup.LinkLabel>
                  {agent.status === Status.enabled ? (
                    <CheckCircleIcon size={12} className="color-fg-success" />
                  ) : (
                    <BlockedIcon size={12} className="color-fg-muted" />
                  )}
                  {agent.policyDisplayText}
                </ControlGroup.LinkLabel>
              </ControlGroup.Item>
            ))}
          </ControlGroup>
        </Stack>

        {canViewThirdPartyAgents && (
          <Stack gap="normal">
            <Stack justify="space-between" direction="horizontal">
              <span>
                {/* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */}
                <Text className="mr-2 fgColor-muted" weight="semibold">
                  Partner Agents
                </Text>
                <Label variant="success">Preview</Label>
              </span>
              <Text size="small" weight="light" className="fgColor-muted">
                Allowed partner agents must be installed on your organizations
              </Text>
            </Stack>

            {thirdPartyAgentsEnabled ? (
              <ControlGroup>
                {thirdPartyAgents.map(agent => {
                  const currentMode = thirdPartyAgentModes[agent.name] ?? agent.mode
                  const canModify = canWrite || canAdmin

                  return (
                    <ThirdPartyAgentSelector
                      key={agent.name}
                      agent={agent}
                      canModify={canModify}
                      currentMode={currentMode}
                      onModeChange={newMode => handleThirdPartyAgentModeChange(agent.name, agent.toggleUrl, newMode)}
                    />
                  )
                })}
              </ControlGroup>
            ) : (
              <Blankslate border>
                <Blankslate.Visual>
                  <AgentIcon size="medium" />
                </Blankslate.Visual>
                <Blankslate.Description>
                  <Text weight="light">
                    To use third-party agents,{' '}
                    <Link inline href="agents/policies">
                      enable <span>{'Copilot cloud agent'}</span>
                    </Link>
                    .
                  </Text>
                </Blankslate.Description>
              </Blankslate>
            )}
          </Stack>
        )}
      </Stack>

      {currentSelection && !validationWarning && !validationLoading && (
        <Stack gap="normal">
          <h2>Custom agents</h2>

          {isLoadingCustomAgents ? (
            <div className="border rounded-2" role="status" aria-label="Loading custom agents">
              {[1, 2, 3].map(i => (
                <div
                  key={i}
                  className="Box-row d-flex flex-row flex-items-start gap-3 tmp-py-3"
                  style={{borderTop: i > 1 ? '1px solid var(--borderColor-default)' : 'none'}}
                >
                  <div className="flex-1">
                    <div className="mb-2">
                      <SkeletonText size="bodyMedium" />
                    </div>
                    <div style={{width: '50%'}}>
                      <SkeletonText size="bodySmall" />
                    </div>
                  </div>
                  <div style={{width: '80px'}}>
                    <SkeletonText size="bodySmall" />
                  </div>
                </div>
              ))}
            </div>
          ) : customAgents.length > 0 ? (
            <ControlGroup>
              {customAgents.map(agent => (
                <ControlGroup.Item href={agent.url} key={agent.name} contentsClassname="tmp-py-3">
                  <ControlGroup.Title>
                    <div className="d-flex flex-row flex-items-center gap-2">
                      <span className="text-bold">{agent.name}</span>
                      <span
                        className={`d-flex flex-row flex-items-center gap-1 fgColor-muted text-small ${styles.CustomAgentTextDescription}`}
                      >
                        <span className={`text-semibold ${styles.CustomAgentTextDescription}`}>
                          @{agent.repo_owner}
                        </span>
                        <span className={styles.CustomAgentTextDescription}>/ {agent.repo_name}</span>
                      </span>
                    </div>
                  </ControlGroup.Title>
                  <ControlGroup.Custom>
                    <div className="d-flex flex-row flex-items-center gap-2 fgColor-muted text-normal">
                      <CheckCircleIcon size={12} className="color-fg-success" />
                      {Status.enabled}
                    </div>
                  </ControlGroup.Custom>
                </ControlGroup.Item>
              ))}
            </ControlGroup>
          ) : (
            <div className="Box-row tmp-py-6 text-center fgColor-muted">No custom agents found.</div>
          )}
        </Stack>
      )}

      <Stack gap="normal">
        <h2>Tracking and governance</h2>
        <ProtectAgents canAdmin={canAdmin} canWrite={canWrite} />
        <ControlGroup>
          <ControlGroup.Item
            href={
              canViewAuditLogs
                ? `/enterprises/${slug}/settings/audit-log?q=${
                    // Check if any third-party agents (Claude or Codex) are enabled
                    payload.data?.third_party_agents?.some(agent => agent.enabled)
                      ? 'actor%3ACopilot+OR+actor%3AClaude+OR+actor%3ACodex'
                      : 'actor%3ACopilot'
                  }`
                : undefined
            }
            leadingIcon={<LogIcon />}
            disabled={!canViewAuditLogs}
          >
            <ControlGroup.Title>Audit logs</ControlGroup.Title>
            <ControlGroup.Description>
              Keep track of agent activity and changes across your enterprise
            </ControlGroup.Description>
          </ControlGroup.Item>
        </ControlGroup>
      </Stack>
    </Stack>
  )
}
