import {AsyncFilterProvider, SelectFilterProvider} from '@github-ui/filter-core/providers'
import {
  type FilterKey,
  type FilterSuggestion,
  type SuppliedFilterProviderOptions,
  type FilterProvider,
  type FilterConfig,
  type AnyBlock,
  type MutableFilterBlock,
  type ARIAFilterSuggestion,
  type FilterValueData,
  type ValueRowProps,
  type AvatarType,
  FilterValueType,
  FilterProviderType,
  FilterQuery,
  getDefaultValueVisualDescriptors,
  getFilterValue,
} from '@github-ui/filter-core'
import {
  IssueDraftIcon,
  AgentIcon,
  OrganizationIcon,
  ArrowSwitchIcon,
  CalendarIcon,
  PersonIcon,
  RepoIcon,
} from '@primer/octicons-react'
import debounce from './debounce'
import type {AgentFilterData, StatusFilterData, TimeframeFilterData} from './sessions-route'

const SUGGESTION_LIMIT = 8

// Priority controls dropdown sort order (ascending). Only priorities ≤ 5 appear in the initial dropdown.
const FILTER_PRIORITY = {
  timeframe: 1,
  status: 2,
  org: 3,
  repo: 4,
  agent: 5,
  user: 5, // When shared priority, agent appears before user because of insertion order in filter list, see `const filterProviders` in sessions-route.tsx
}

/**
 * Agent filter provider with server-provided agent options
 */
export class AgentFilterProvider extends SelectFilterProvider {
  constructor(agentOptions: AgentFilterData[], options?: SuppliedFilterProviderOptions) {
    const filterKey: FilterKey = {
      displayName: 'Agent',
      key: 'agent',
      priority: FILTER_PRIORITY.agent,
      icon: AgentIcon,
      description: 'Filter by agent type',
    }

    const filterValues: FilterSuggestion[] = agentOptions.map((agent, index) => ({
      value: agent.value,
      displayName: agent.display_name,
      type: FilterValueType.Value,
      priority: index + 1,
      avatar: agent.avatar_url ? {url: agent.avatar_url, type: 'user' as AvatarType} : undefined,
    }))

    super(filterKey, filterValues, {
      ...options,
      strictMatching: true, // Only allow values from the list
      filterTypes: {
        inclusive: true, // Allow "agent:claude"
        exclusive: false, // Hide "Exclude agent"
        valueless: false, // Hide "No agent"
        hasValue: false, // Hide "Has agent"
        multiValue: true, // Allow comma-separated agent values (OR)
        multiKey: false, // Prevent multiple "agent:" keys in the same query
      },
    })
  }
}

/**
 * Timeframe filter provider with server-provided timeframe options
 */
export class TimeframeFilterProvider extends SelectFilterProvider {
  constructor(timeframeOptions: TimeframeFilterData[], options?: SuppliedFilterProviderOptions) {
    const filterKey: FilterKey = {
      displayName: 'Timeframe',
      key: 'timeframe',
      priority: FILTER_PRIORITY.timeframe,
      icon: CalendarIcon,
      description: 'Filter by timeframe',
    }

    // Use server-provided options
    const filterValues: FilterSuggestion[] = timeframeOptions.map((tf, index) => ({
      value: tf.value,
      displayName: tf.display_name,
      type: FilterValueType.Value,
      priority: index + 1,
      icon: ArrowSwitchIcon,
    }))

    super(filterKey, filterValues, {
      ...options,
      strictMatching: true, // Only allow values from the list
      filterTypes: {
        inclusive: true, // Allow "timeframe:24h"
        exclusive: false, // Hide "Exclude timeframe"
        valueless: false, // Hide "No timeframe"
        hasValue: false, // Hide "Has timeframe"
        multiValue: false, // Only allow a single timeframe value
        multiKey: false, // Prevent multiple "timeframe:" keys in the same query
      },
    })
  }
}

type OrgSuggestion = {
  id: number
  name: string
  avatar_url?: string
}

type RepoSuggestion = {
  name: string
  value: string
  description: string
}

type BaseSuggestion = {
  name: string
}

/**
 * Base class for async filter providers that fetch suggestions from an API endpoint
 */
abstract class BaseAsyncFilterProvider<T extends BaseSuggestion>
  extends AsyncFilterProvider<T>
  implements FilterProvider
{
  protected abstract entityName: string
  protected abstract avatarType: AvatarType | undefined

  constructor(
    filterKey: FilterKey,
    suggestionsUrl: string,
    options?: SuppliedFilterProviderOptions,
    filterTypesOverride?: Partial<SuppliedFilterProviderOptions['filterTypes']>,
  ) {
    super(filterKey, {
      ...options,
      filterTypes: {
        inclusive: true,
        exclusive: false,
        valueless: false,
        hasValue: false,
        multiValue: true,
        multiKey: false,
        ...filterTypesOverride,
      },
    })
    this.suggestionEndpoint = suggestionsUrl
    this.validationEndpoint = suggestionsUrl
    this.type = FilterProviderType.Select

    // Debounce API requests to avoid excessive calls as user types
    // Nested promises are flattened in javascript, so Promise<Promise<T>> == Promise<T>
    // TypeScript doesn't know this, so casting through unknown first
    // https://github.com/microsoft/TypeScript/issues/27711
    this.fetchData = debounce(this.fetchData.bind(this), 500) as unknown as (
      apiURL: string,
      abortController?: AbortController,
    ) => Promise<Response | undefined>
  }

  async getSuggestions(
    filterQuery: FilterQuery,
    filterBlock: AnyBlock | MutableFilterBlock,
    _config: FilterConfig,
    caretIndex?: number | null,
  ): Promise<ARIAFilterSuggestion[] | null> {
    return this.processSuggestions(filterQuery, filterBlock, this.processSuggestion.bind(this), caretIndex)
  }

  protected processSuggestion(item: T, _query: string, _filterQuery: FilterQuery): ARIAFilterSuggestion {
    return {
      type: FilterValueType.Value,
      value: item.name,
      displayName: item.name,
      ariaLabel: `${item.name}, ${this.entityName}`,
      avatar: this.getAvatar(item),
      priority: 0,
      inlineDescription: false,
    }
  }

  protected getAvatar(_item: T): {url: string; type: AvatarType} | undefined {
    return undefined
  }

  override async fetchSuggestions(
    value: string,
    _block: AnyBlock | MutableFilterBlock,
    _filterQuery: FilterQuery,
  ): Promise<T[] | null> {
    try {
      if (this.suggestionCache.has(value)) {
        return this.suggestionCache.get(value) ?? []
      }

      if (!this.suggestionEndpoint) throw new Error('No suggestion endpoint provided')

      const endpoint = `${this.suggestionEndpoint}?q=${encodeURIComponent(value)}&limit=${SUGGESTION_LIMIT}`
      const response = await this.fetchData(endpoint, this.abortSuggestionsController)

      if (!response || !response.ok) {
        return null
      }

      const data = await response.json()
      const suggestions = data.suggestions || []

      if (Array.isArray(suggestions) && suggestions.length < SUGGESTION_LIMIT) {
        this.completeResultSetQueries.add(value)
      }

      this.suggestionCache.set(value, suggestions)
      return suggestions
    } catch {
      return null
    }
  }

  override async validateFilterValue(
    value: string,
    _fetchParams?: URLSearchParams,
    filterQuery?: FilterQuery,
  ): Promise<T | Error | null> {
    if (this.validationCache.has(value)) {
      return this.validationCache.get(value) ?? null
    }

    // Check suggestion cache first
    for (const suggestions of this.suggestionCache.values()) {
      const match = suggestions.find((x: T) => x.name.toLowerCase() === value.toLowerCase())
      if (match) {
        this.validationCache.set(value, match)
        return match
      }
    }

    // Cache miss - validate with API call
    try {
      if (!this.suggestionEndpoint) throw new Error('No suggestion endpoint provided')

      const endpoint = `${this.suggestionEndpoint}?q=${encodeURIComponent(value)}&limit=1`

      this.abortPreviousValidationRequests(filterQuery)
      const response = await this.fetchData(endpoint, this.abortValidationController)
      if (!response) return new Error('Aborted')
      if (!response.ok) return null

      const data = await response.json()
      const suggestions = data.suggestions || []
      const validationData = suggestions.find((x: T) => x.name.toLowerCase() === value.toLowerCase())

      if (validationData) {
        this.validationCache.set(value, validationData)
      }
      return validationData || null
    } catch {
      return null
    }
  }

  getValueRowProps(value: FilterValueData): ValueRowProps {
    return {
      text: value.displayName ?? getFilterValue(value.value) ?? '',
      description: value.description,
      descriptionVariant: 'block',
      leadingVisual: getDefaultValueVisualDescriptors(value, this.icon, true),
    }
  }
}

type UserSuggestion = {
  id: number
  name: string
  full_name?: string
  avatar_url?: string
}

/**
 * Organization filter provider using server-backed suggestions
 * Fetches org suggestions dynamically as user types
 */
export class OrgFilterProvider extends BaseAsyncFilterProvider<OrgSuggestion> {
  protected entityName = 'Organization'
  protected avatarType: AvatarType = 'org'

  constructor(orgSuggestionsUrl: string, options?: SuppliedFilterProviderOptions) {
    super(
      {
        displayName: 'Organization',
        key: 'org',
        priority: FILTER_PRIORITY.org,
        icon: OrganizationIcon,
        description: 'Filter by organization',
      },
      orgSuggestionsUrl,
      options,
    )
  }

  protected override getAvatar(item: OrgSuggestion): {url: string; type: AvatarType} | undefined {
    return item.avatar_url ? {url: item.avatar_url, type: this.avatarType} : undefined
  }
}

/**
 * Repository filter provider using server-backed suggestions
 * Fetches repo suggestions dynamically as user types
 */
export class RepoFilterProvider extends BaseAsyncFilterProvider<RepoSuggestion> {
  protected entityName = 'Repository'
  protected avatarType: AvatarType | undefined = undefined

  constructor(repoSuggestionsUrl: string, options?: SuppliedFilterProviderOptions) {
    super(
      {
        displayName: 'Repository',
        key: 'repo',
        priority: FILTER_PRIORITY.repo,
        icon: RepoIcon,
        description: 'Filter by repository',
      },
      repoSuggestionsUrl,
      options,
    )
  }

  protected override processSuggestion(
    item: RepoSuggestion,
    _query: string,
    _filterQuery: FilterQuery,
  ): ARIAFilterSuggestion {
    return {
      type: FilterValueType.Value,
      value: item.value,
      displayName: item.name,
      description: item.description,
      ariaLabel: `${item.name}, ${this.entityName}`,
      priority: 0,
      inlineDescription: false,
    }
  }
}

/**
 * User filter provider using server-backed suggestions
 * Fetches user suggestions dynamically as user types
 */
export class UserFilterProvider extends BaseAsyncFilterProvider<UserSuggestion> {
  protected entityName = 'User'
  protected avatarType: AvatarType = 'user'

  constructor(userSuggestionsUrl: string, options?: SuppliedFilterProviderOptions) {
    super(
      {
        displayName: 'User',
        key: 'user',
        priority: FILTER_PRIORITY.user,
        icon: PersonIcon,
        description: 'Filter by session actor',
      },
      userSuggestionsUrl,
      options,
    )
  }

  protected override processSuggestion(
    user: UserSuggestion,
    _query: string,
    _filterQuery: FilterQuery,
  ): ARIAFilterSuggestion {
    return {
      type: FilterValueType.Value,
      value: user.name,
      displayName: user.name,
      description: user.full_name,
      ariaLabel: `${user.name}, User`,
      avatar: this.getAvatar(user),
      priority: 0,
      inlineDescription: true,
    }
  }

  protected override getAvatar(item: UserSuggestion): {url: string; type: AvatarType} | undefined {
    return item.avatar_url ? {url: item.avatar_url, type: this.avatarType} : undefined
  }

  override getValueRowProps(value: FilterValueData): ValueRowProps {
    return {
      text: value.displayName ?? getFilterValue(value.value) ?? '',
      description: value.description,
      descriptionVariant: 'inline',
      leadingVisual: getDefaultValueVisualDescriptors(value, this.icon),
    }
  }
}

/**
 * Static status filter
 */
export class StatusFilterProvider extends SelectFilterProvider {
  constructor(statusDisplayNames: StatusFilterData[], options?: SuppliedFilterProviderOptions) {
    const filterKey: FilterKey = {
      displayName: 'Status',
      key: 'status',
      priority: FILTER_PRIORITY.status,
      icon: IssueDraftIcon,
      description: 'Filter by session status',
    }

    const filterValues: FilterSuggestion[] = statusDisplayNames.map(({name, display_name}, index) => ({
      value: name,
      displayName: display_name,
      type: FilterValueType.Value,
      priority: index + 1,
    }))

    super(filterKey, filterValues, {
      ...options,
      strictMatching: true, // Only allow values from the list
      filterTypes: {
        inclusive: true, // Allow "status:in_progress"
        exclusive: false, // Hide "Exclude status"
        valueless: false, // Hide "No status"
        hasValue: false, // Hide "Has status"
        multiValue: true, // Allow "status:completed,failed"
        multiKey: false, // Disallow multiple "status:" keys in the same query
      },
    })
  }
}
