import {useRef, useState} from 'react'
import {PackageIcon} from '@primer/octicons-react'
import {Button, Dialog, Label} from '@primer/react'
import {ControlGroup as ControlGroupNew} from '@github-ui/control-group'
import {EnterpriseControlGroup} from '@github-ui/enterprise-control-group'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import styles from './EnterpriseManagedSettings.module.css'

type SettingsJson = Record<string, unknown> & {
  enabledPlugins?: Record<string, unknown>
}

type EnterpriseManagedSettingsProps = {
  settings: SettingsJson
}

export function EnterpriseManagedSettings({settings}: EnterpriseManagedSettingsProps) {
  const controlGroupUnificationEnabled = isFeatureEnabled('control-group-unification')
  const ControlGroup = controlGroupUnificationEnabled ? ControlGroupNew : EnterpriseControlGroup

  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const buttonRef = useRef<HTMLButtonElement>(null)

  const pluginCount = settings.enabledPlugins ? Object.keys(settings.enabledPlugins).length : 0
  const formattedSettings = JSON.stringify(settings, null, 2)

  return (
    <>
      <ControlGroup>
        <ControlGroup.Item leadingIcon={<PackageIcon />}>
          <ControlGroup.Title>
            <div className="d-flex flex-items-center gap-2">
              <span>Plugins</span>
              <Label variant="success">Preview</Label>
            </div>
          </ControlGroup.Title>
          <ControlGroup.Description>
            <span>{`${pluginCount} ${pluginCount === 1 ? 'plugin' : 'plugins'} configured via enabledPlugins in settings.json`}</span>
          </ControlGroup.Description>
          <ControlGroup.Custom>
            <Button ref={buttonRef} onClick={() => setIsDialogOpen(true)} size="small">
              View settings.json
            </Button>
          </ControlGroup.Custom>
        </ControlGroup.Item>
      </ControlGroup>
      {isDialogOpen && (
        <Dialog title="settings.json" onClose={() => setIsDialogOpen(false)} returnFocusRef={buttonRef} width="large">
          <div role="region" aria-label="Settings file contents" className={styles.codeBlock}>
            <pre className={styles.codeBlockPre}>
              <code>{formattedSettings}</code>
            </pre>
          </div>
        </Dialog>
      )}
    </>
  )
}
